def has_8_between(p1, p2):
    """Check if there's an 8 strictly between p1 and p2 along the straight line"""
    r1, c1 = p1
    r2, c2 = p2

    # Horizontal
    if r1 == r2 and c1 < c2:
        for c in range(c1 + 1, c2):
            if (r1, c) in eights:
                return True
    elif r1 == r2 and c2 < c1:
        for c in range(c1 + 1, c2, -1):
            if (r1, c) in eights:
                return True
    # Vertical
    elif c1 == c2 and r1 < r2:
        for r in range(r1 + 1, r2):
            if (r, c1) in eights:
                return True
    elif c1 == c2 and r2 < r1:
        for r in range(r1 + 1, r2, -1):
            if (r, c1) in eights:
                return True
    return False

