minimal_pairs_h = []  # horizontal
minimal_pairs_v = []  # vertical

for r in range(len(grid)):
    cols_with_8 = sorted([c for c in range(len(grid[0])) if grid[r][c] == 8])
    for i in range(len(cols_with_8)):
        for j in range(i+1, len(cols_with_8)):
            if not has_8_between((r, cols_with_8[i]), (r, cols_with_8[j])):
                minimal_pairs_h.append(((r, cols_with_8[i]), (r, cols_with_8[j])))

for c in range(len(grid[0])):
