    for i in range(len(rows_with_8)):
        for j in range(i+1, len(rows_with_8)):
            if not has_8_between((rows_with_8[i], c), (rows_with_8[j], c)):
                minimal_pairs_v.append(((rows_with_8[i], c), (rows_with_8[j], c)))

