# Draw rectangles for minimal pairs only
border_val = 7
test_grid = [row[:] for row in grid]

def draw_rect_preserving_corners_minimal(grid, r1, c1, r2, c2, fill_val, eights_set):
    """Draw rectangular border preserving original 8s at corners"""

    def check_not_eight(pos):
        return pos not in eights_set

    # Top edge
    for c in range(c1, c2 + 1):
        if check_not_eight((r1, c)):
            grid[r1][c] = fill_val

    # Bottom edge
    for c in range(c1, c2 + 1):
        if check_not_eight((r2, c)):
            grid[r2][c] = fill_val

    # Left edge
    for r in range(r1, r2 + 1):
        if check_not_eight((r, c1)):
            grid[r][c1] = fill_val

    # Right edge
    for r in range(r1, r2 + 1):
        if check_not_eight((r, c2)):
            grid[r][c2] = fill_val

rectangles = set()
for p1, p2 in minimal_pairs_h + minimal_pairs_v:
    rect = (tuple(sorted((min(p1[0], p2[0]), min(p1[1], p2[1])), 
                          (max(p1[0], p2[0]), max(p1[1], p2[1])))))
    rectangles.add(rect)

for ((r1, c1), (r2, c2)) in sorted(rectangles, key=lambda x: (x[0][0], x[1][0], x[0][1])):
